import os, re

root = "/bench/repo"
# Match store.Memo as a type, not MemoShare/MemoRelation/etc
pat_qualified = re.compile(r'store\.Memo\b(?![A-Za-z])')
# In store package itself, Memo as type - harder. We'll scan store/*.go excluding tests first

skip_dirs = {'.git', 'web', 'node_modules', 'proto/gen'}
files = []
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in {'.git', 'node_modules', 'web'} and not d.startswith('.')]
    if '/proto/gen/' in dirpath + '/' or dirpath.endswith('/proto/gen'):
        continue
    for fn in filenames:
        if fn.endswith('.go'):
            files.append(os.path.join(dirpath, fn))

qualified = {}
for path in files:
    try:
        text = open(path).read()
    except Exception:
        continue
    if pat_qualified.search(text):
        rel = path[len(root)+1:]
        # count only true store.Memo
        hits = pat_qualified.findall(text)
        if hits:
            qualified[rel] = len(hits)

print("=== qualified store.Memo ===")
for p in sorted(qualified):
    print(f"{qualified[p]:4} {p}")

print("\n=== store package Memo type refs ===")
# store package uses Memo without prefix
store_dir = os.path.join(root, "store")
# types that start with Memo
# Look for *Memo, []Memo, []*Memo, Memo{, (Memo), *Memo,
pat_local = re.compile(r'(?<![A-Za-z])Memo\b(?![A-Za-z])')
# exclude comments? keep simple
for dirpath, dirnames, filenames in os.walk(store_dir):
    dirnames[:] = [d for d in dirnames if d not in {'test'}]
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        rel = path[len(root)+1:]
        text = open(path).read()
        # skip if no Memo
        if 'Memo' not in text:
            continue
        # find lines with standalone Memo as type-ish
        lines = []
        for i, line in enumerate(text.splitlines(), 1):
            if pat_local.search(line) and not line.strip().startswith('//'):
                # exclude MemoRelation, MemoShare, etc already by word boundary after Memo
                # but MemoRelation has more letters so \b after Memo would fail for MemoRelation... 
                # \b after Memo matches between o and R? No, MemoRelation is one word, \b is between word and non-word.
                # MemoRelation: Memo is not a word by itself.
                lines.append(f"  {i}:{line.strip()[:120]}")
        if lines:
            print(rel)
            for l in lines[:15]:
                print(l)
            if len(lines) > 15:
                print(f"  ... +{len(lines)-15} more")
